// Builds the /tm/ page script (site/tm/tm.js): src/browser/tm-run-global.ts bundled for the browser. Same pattern as
// scripts/build-loader.ts.
//
//   bun scripts/build-tm.ts           write the file
//   bun scripts/build-tm.ts --check   exit 1 if the committed file differs from a fresh build

import { join } from "node:path";

const ROOT = join(import.meta.dir, "..");
export const TM_OUT = join(ROOT, "site", "tm", "tm.js");
export const TM_ENTRY = join(ROOT, "src", "browser", "tm-run-global.ts");

const HEADER = `/*
 * GENERATED by scripts/build-tm.ts: src/browser/tm-run-global.ts bundled for the browser (The Run on /tm/).
 * No network calls. Do not edit; rerun the script.
 */
`;

export async function bundleTm(entry = TM_ENTRY): Promise<string> {
  const r = await Bun.build({ entrypoints: [entry], target: "browser", format: "iife", minify: false });
  const out = r.outputs[0];
  if (!r.success || out === undefined) throw new Error(`tm bundle failed: ${r.logs.map(String).join("; ")}`);
  return `${HEADER}${await out.text()}`;
}

if (import.meta.main) {
  const args = process.argv.slice(2);
  if (args.length > 1 || (args.length === 1 && args[0] !== "--check")) {
    console.error("usage: bun scripts/build-tm.ts [--check]");
    process.exit(2);
  }
  const built = await bundleTm();
  if (args[0] === "--check") {
    const same = (await Bun.file(TM_OUT).text().catch(() => "")) === built;
    console.log(same ? "tm.js up to date" : "stale: site/tm/tm.js; run bun scripts/build-tm.ts");
    process.exit(same ? 0 : 1);
  }
  await Bun.write(TM_OUT, built);
  console.log(`wrote site/tm/tm.js (${built.length} bytes)`);
}
